{
  "apiVersion": 1,
  "type": "component.detail",
  "package": "@astryxdesign/core",
  "data": {
    "name": "DrawerHeader",
    "subComponentOf": "Drawer",
    "displayName": "Drawer Header",
    "registry": {
      "aliases": [
        "lab/drawer-header"
      ]
    },
    "isHiddenFromOverview": true,
    "description": "Header for drawers with a title, optional subtitle, close button, and start/end content slots. Same API as DialogHeader.",
    "usage": {
      "description": "Compose DrawerHeader in the header slot of a Layout inside the Drawer, as DialogHeader is composed in Dialog, for a title row and, when you pass onOpenChange, a close button. The Layout keeps the header on the drawer inset instead of padding it twice. Drawer renders no close button of its own. Unlike DialogHeader it does not take focus on open (Drawer uses data-autofocus) and does not name the drawer (Drawer label does).",
      "anatomy": [
        {
          "name": "Header row",
          "required": true,
          "description": "Arranges the title block, optional start/end content, and close control."
        },
        {
          "name": "Start content",
          "required": false,
          "description": "Wraps optional leading content."
        },
        {
          "name": "Title block",
          "required": true,
          "description": "Groups the title and optional subtitle."
        },
        {
          "name": "End content",
          "required": false,
          "description": "Groups optional trailing content with the optional close control."
        },
        {
          "name": "Close icon",
          "required": false,
          "description": "Visual close glyph inside the close button."
        }
      ]
    },
    "props": [
      {
        "name": "title",
        "type": "ReactNode",
        "description": "Drawer title, rendered as an h2. Keep it inline and non-interactive. It does not name the drawer; pass Drawer a label.",
        "required": true
      },
      {
        "name": "subtitle",
        "type": "ReactNode",
        "description": "Subtitle below the title. Accepts inline content such as a Link; avoid block elements."
      },
      {
        "name": "onOpenChange",
        "type": "(isOpen: boolean) => unknown",
        "description": "Close button callback, called with false (no button if omitted). Pass the Drawer's own onOpenChange."
      },
      {
        "name": "startContent",
        "type": "ReactNode",
        "description": "Content before the title (e.g., a back button)."
      },
      {
        "name": "endContent",
        "type": "ReactNode",
        "description": "Content after the title, before the close button."
      },
      {
        "name": "endContentEdgeCompensation",
        "type": "'inline' | 'block' | 'all'",
        "description": "Selects compensation axes for the end-content slot. Omit to preserve automatic close-action compensation."
      },
      {
        "name": "hasDivider",
        "type": "boolean",
        "description": "Adds a border at the bottom edge. Defaults to the parent Layout's defaultHasDividers."
      }
    ],
    "playground": {
      "defaults": {
        "title": "Host details",
        "subtitle": "web-prod-04",
        "hasDivider": true
      }
    },
    "theming": {
      "targets": [
        {
          "className": "astryx-drawer-header"
        },
        {
          "className": "astryx-drawer-header-start-content"
        },
        {
          "className": "astryx-drawer-header-title-block"
        },
        {
          "className": "astryx-drawer-header-end-content"
        },
        {
          "className": "astryx-drawer-header-close-icon"
        }
      ]
    },
    "examples": [
      {
        "label": "With close button",
        "code": "\nimport {useState} from 'react';\nimport {Drawer, DrawerHeader} from '@astryxdesign/core/Drawer';\nimport {Layout, LayoutContent} from '@astryxdesign/core/Layout';\n\nfunction Inspector() {\n  const [isOpen, setIsOpen] = useState(true);\n\n  // Passing onOpenChange renders a close button that calls it with false.\n  return (\n    <Drawer isOpen={isOpen} onOpenChange={setIsOpen} label=\"Details\">\n      <Layout\n        header={<DrawerHeader title=\"Details\" onOpenChange={setIsOpen} />}\n        content={<LayoutContent>Content</LayoutContent>}\n      />\n    </Drawer>\n  );\n}\n"
      },
      {
        "label": "With subtitle and end content",
        "code": "\nimport {DrawerHeader} from '@astryxdesign/core/Drawer';\nimport {Badge} from '@astryxdesign/core/Badge';\n\n<DrawerHeader\n  title=\"web-prod-04\"\n  subtitle=\"us-east-1\"\n  endContent={<Badge label=\"Healthy\" />}\n/>;\n"
      }
    ],
    "package": "@astryxdesign/core",
    "import": "@astryxdesign/core/Drawer",
    "sourceAvailable": true
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
